'use strict';
const groups={Auth:['Splash','Login','Login · error','Sign up','Verify OTP','Forgot password','Verify reset','Reset password'],Subscriptions:['Home','Home · first visit','Home · empty','Home · money','Home · quiet','List','List · empty','List · upcoming','List · no renewal','Add sheet','Add form','Detail','Detail · cancelled','Detail · no renewal','Edit','AI chat','Voice','Gmail · scanning','Gmail · review','Gmail · nothing found','Paywall','Delete confirm','Widgets'],Alerts:['Alerts','Alerts · empty'],Profile:['Profile','Profile · incomplete','Edit profile','Change password','History','History · empty','Payments','Payments · empty']};
const slug=s=>s.toLowerCase().replace(/ · /g,'-').replace(/\s+/g,'-');
const screens=Object.values(groups).flat();
let current='Home',previous='Home',demoName='Netflix',demoPrice='15.99';
const state={reminder:true,cycle:'Monthly',plan:'Monthly',created:false};
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,to,cls='primary')=>`<button class="${cls}" data-go="${escape(to)}">${label}</button>`;
const action=(label,name,cls='secondary')=>`<button class="${cls}" data-action="${name}">${label}</button>`;
const input=(label,value='',type='text',name='')=>`<label>${label}<input type="${type}" name="${name||slug(label)}" value="${escape(value)}" ${label.includes('optional')?'':'required'} ${type==='password'?'minlength="6"':type==='number'?'step="0.01" min="0"':''}></label>`;
const fr=(a,b)=>`<div class="fieldrow"><span>${a}</span><span>${b}</span></div>`;
const panel=x=>`<div class="panel">${x}</div>`;
const heading=(title,back=false,plus=false)=>`<div class="head">${back?btn('‹','back','back'):''}<h2>${title}</h2>${plus?btn('+','Add sheet','plus'):''}</div>`;
const brand=()=>`<div class="brand"><img src="assets/renewless-mark.svg" alt="Renewless R"><span>Renewless</span></div><p class="tagline">Stop the subscription renewals you don’t need.</p>`;
const loop=()=>`<button data-action="loop" aria-label="React with Loop"><img class="loop" src="assets/loop-mascot.svg" alt="Loop companion"></button>`;
const empty=(title,copy,cta=false,mascot=true)=>`<div class="empty">${mascot?loop():''}<h3>${title}</h3><p>${copy}</p>${cta?btn('Add manually','Add form')+btn('Connect Gmail','Gmail · scanning','secondary'):''}</div>`;
const icons={Home:'<path d="m3 10 9-7 9 7v10H3z M9 20v-7h6v7"/>',List:'<path d="M8 5h13M8 12h13M8 19h13M3 5h1M3 12h1M3 19h1"/>',Alerts:'<path d="M5 17h14l-2-4V9a5 5 0 0 0-10 0v4zM10 21h4"/>',Profile:'<circle cx="12" cy="7" r="3"/><path d="M5 21v-3a7 7 0 0 1 14 0v3"/>'};
const tabs=()=>`<nav class="tabs" aria-label="App navigation">${Object.keys(icons).map(t=>`<button class="${current.startsWith(t)?'selected':''}" data-go="${t}"><svg viewBox="0 0 24 24" aria-hidden="true">${icons[t]}</svg>${t}</button>`).join('')}</nav>`;
const rows=(kind='normal')=>`<div class="rows">${(kind==='history'?[['Disney+','13.99','Expired'],['Adobe','59.99','Cancelled'],['NYT','17.00','Expired']]:kind==='none'?[['Notion','10.00','No renewal'],['Figma','15.00','No renewal']]:[[demoName,demoPrice,'27 Oct · Estimated'],['Spotify','11.99','29 Oct'],['iCloud+','2.99','30 Oct']]).map(([name,price,date])=>`<button class="row" data-go="${kind==='none'?'Detail · no renewal':kind==='history'?'Detail · cancelled':'Detail'}" data-name="${escape(name)}" data-price="${price}"><span class="avatar">${escape(name[0])}</span><span class="body"><strong>${escape(name)}</strong><small>${date}</small></span><span class="amount">$${price}<small>${kind==='history'?'History':kind==='none'?'Needs date':'Upcoming'}</small></span></button>`).join('')}</div>`;
const stats=()=>`<div class="stats">${[['Active',state.created?'13':'12'],['Renewing soon','3'],['This month','$86'],['Expired','2']].map(([a,b])=>panel(`<span class="metric-label">${a}</span><strong ${a==='Expired'?'class="danger"':''}>${b}</strong>`)).join('')}</div>`;
function auth(){
 if(current==='Splash')return `<div class="splash">${brand()}<small>Restoring your session</small>${btn('Preview login','Login','link')}</div>`;
 if(current==='Login'||current==='Login · error')return `${brand()}<form data-submit="Home">${input('Email','alex@example.com','email')}${input('Password','sample123','password')}${current.includes('error')?'<p class="error">Wrong email or password. Please try again.</p>':''}<button class="primary">Log in</button></form>${btn('Forgot password','Forgot password','link')}${btn('Continue with Google','Home','secondary')}${btn('Continue with Apple','Home','secondary')}${btn('New here? Sign up','Sign up','link')}<p class="note">Demo only. Use fictional details; nothing is sent.</p>`;
 if(current==='Sign up')return `${brand()}<form data-submit="Verify OTP">${input('Name','Alex Morgan')}${input('Email','alex@example.com','email')}${input('Password','sample123','password')}${input('Phone · optional','','tel')}${input('Date of birth · optional','','date')}<label>Gender · optional<select><option>Not set</option><option>Female</option><option>Male</option><option>Other</option></select></label><button class="primary">Create account</button></form>${btn('Continue with Google','Home','secondary')}${btn('Continue with Apple','Home','secondary')}${btn('Already have an account? Log in','Login','link')}`;
 if(current==='Verify OTP'||current==='Verify reset')return `${heading(current==='Verify OTP'?'Verify email':'Reset code',true)}<p class="muted">Enter the six-digit code sent to your email.</p>${input('Email','alex@example.com','email')}<form data-submit="${current==='Verify OTP'?'Home':'Reset password'}"><label>Code</label><div class="otp">${'481926'.split('').map((v,i)=>`<input aria-label="Digit ${i+1}" maxlength="1" pattern="[0-9]" inputmode="numeric" value="${v}" required>`).join('')}</div><p class="note">Expires in 5 minutes · resend after 2 minutes</p><button class="primary">Verify</button></form>${action('Resend code','resend','link')}`;
 if(current==='Forgot password')return `${heading('Forgot password',true)}<p class="muted">We’ll send a code to reset your password.</p><form data-submit="Verify reset">${input('Email','alex@example.com','email')}<button class="primary">Send code</button></form>`;
 return `${heading('New password',true)}<form data-submit="Login">${input('New password','','password')}${input('Confirm password','','password')}<button class="primary">Save</button></form><p class="note">Save returns to Login. Your session is not started automatically.</p>`;
}
function home(up){
 let h=heading('Home',false,true);if(current==='Home · first visit')h+='<p class="eyebrow" style="text-align:right">↗ Add a subscription.</p>';
 if(current==='Home · empty')return h+empty('Your subscriptions, in one place','Add your first subscription to see what renews next.',true);
 const money=current==='Home · money';
 const recommendation=`<p class="eyebrow">${money?'BIGGEST UPCOMING CHARGE':'RENEWS SOON'}</p><p>${money?'Cursor · $20 — biggest charge in the next 7 days.':escape(demoName)+' renews in 3 days.'}</p>${action(money?'Worth it':'Keep it','keep','primary')}${action(money?'Too expensive':'I’ll cancel on the service','cancel-intent',up?'secondary quiet-action':'secondary')}${btn('Already cancelled','Detail · cancelled',up?'link':'secondary')}`;
 const hero=`<section class="hero"><div class="hero-top"><span class="eyebrow">NEXT RENEWAL · IN 3 DAYS</span><span class="avatar">${escape(demoName[0])}</span></div><h3 class="hero-name">${escape(demoName)}</h3><p class="muted" style="margin:0">Entertainment · Monthly</p><div class="hero-price">$${escape(demoPrice)}</div>${btn('View subscription','Detail')}<p class="note">27 October · Estimated</p></section>`;
 if(current==='Home · quiet')return h+stats()+empty('Nothing renewing soon','You’re clear for the next 7 days.',false)+rows();
 return h+(up?hero.replace('<p class="note">27 October · Estimated</p>', '<p class="note">27 October · Estimated</p>'+action(money?'Worth it':'Keep it','keep','secondary')+action(money?'Too expensive':'I’ll cancel on the service','cancel-intent','secondary quiet-action')+btn('Already cancelled','Detail · cancelled','link'))+stats():stats()+`<div class="panel rec">${recommendation}</div>`)+`<h3>Upcoming <small style="float:right">Next 7 days</small></h3>`+rows();
}
function list(){let h=heading('Subscriptions',false,true);if(current==='List · empty')return h+empty('No subscriptions yet','Keep track of what matters to you.',true);return h+`<label>Search<input data-search-rows placeholder="Search subscriptions"></label><div class="chips">${['All','Upcoming','No renewal'].map(t=>btn(t,t==='All'?'List':'List · '+t.toLowerCase(),`chip ${current===(t==='All'?'List':'List · '+t.toLowerCase())?'selected':''}`)).join('')}</div>`+rows(current==='List · no renewal'?'none':'normal');}
function detail(up){const no=current==='Detail · no renewal',cancel=current==='Detail · cancelled';return heading('Detail',true)+`<div class="${up?'hero':'panel'}">${up?`<div class="hero-top"><span class="eyebrow">SUBSCRIPTION</span><span class="avatar">${escape(demoName[0])}</span></div>`:''}<p class="hero-name">${escape(demoName)}</p><small>Entertainment · ${no?'Cycle not set':'Monthly'}</small><p class="hero-price">$${escape(demoPrice)}</p>${up?`<p class="note">${no?'Add a date to schedule reminders':cancel?'Access until 27 October':'Next renewal · 27 October · Estimated'}</p>`:''}</div>${up?'<p class="group-label">Renewal & billing</p>':''}${panel(fr('Status',no?'No renewal':cancel?'Cancelled · access ending':'Upcoming')+fr(cancel?'Access until':'Next renewal',no?'Not set':'27 Oct · Estimated')+fr('Start date','27 Sep 2026')+fr('Paid on this one',no?'—':'$15.99 · Estimated')+fr('Source','Manual'))}${up?'<p class="group-label">Reminder</p>':''}${panel(`<div class="fieldrow"><span>Reminder</span><button data-action="reminder" aria-pressed="${state.reminder}">${state.reminder?'On · 3 days before':'Off'} ›</button></div>`)}${btn('Edit','Edit',up?'primary':'secondary')}${cancel?'<p class="note">This only updates your record in Renewless. It does not cancel the real service.</p>':btn('I cancelled this','Detail · cancelled','secondary')}${btn('Delete','Delete confirm','danger danger-action')}`;}
function addForm(edit){return heading(edit?'Edit':'Add',true)+`<form data-submit="save-sub">${input('Name',demoName,'text','name')}<p class="note">Catalog match</p><label>Category<select name="category"><option>Entertainment</option><option>Productivity</option><option>Education</option></select></label><div class="split">${input('Price',demoPrice,'number','price')}<label>Currency<select name="currency"><option>USD</option><option>EUR</option><option>PKR</option></select></label></div><label>Cycle</label><div class="chips">${['Weekly','Monthly','Yearly'].map(v=>`<button type="button" class="chip ${state.cycle===v?'selected':''}" data-cycle="${v}">${v}</button>`).join('')}</div>${input('Start date · optional','2026-09-27','date')}${input('Next renewal','2026-10-27','date')}<p class="note">Estimated from start date and cycle.</p>${input('Note · optional')}<button class="primary">Save</button></form>`;}
function chat(up){return heading('Add with Loop',true)+`<p class="note">Demo conversation · no AI or microphone connection</p><div class="bubble user">${current==='Voice'?'<span class="voice">▂▅▃▆▂▅▃</span><br><small>Voice message · 0:06</small>':'I pay $9.99 for Duolingo monthly, next renewal October 20.'}</div><div class="bubble bot">I’ve prepared your subscription. Check the details below, or tell me what to change.</div><div class="panel chat-summary">${up?'<p class="eyebrow">READY TO CREATE</p><div class="summary-title"><span class="avatar">D</span><strong>Duolingo</strong></div>':'<h3>Duolingo</h3>'}<p class="hero-price">$9.99 <small>USD</small></p>${fr('Category','Education')}${fr('Billed','Monthly')}${fr('Next renewal','20 Oct 2026')}${fr('Start date','Not set')}${fr('Note','—')}${action('Create','create-ai','primary')}<p class="note">Need a correction? Tell Loop in the chat.</p></div><form data-submit="chat" class="composer"><input aria-label="Message Loop" placeholder="Message Loop…" required><button aria-label="Send message">↑</button></form>${action('Attach image','attach','link')}<input type="file" accept="image/*" class="attachment" hidden><p class="note">Production sends attached images to Gemini. This prototype uploads nothing.</p>`;}
function gmail(){let h=heading('Connect Gmail',true);if(current.endsWith('scanning'))return h+`<div class="empty"><h3>Looking for subscriptions</h3><p>Reviewing the last 12 months of mail.</p><div class="progress"><span></span></div><p class="note">Sample scan · no inbox connected</p>${btn('Preview completed scan','Gmail · review')}${btn('Preview no results','Gmail · nothing found','link')}</div>`;if(current.endsWith('nothing found'))return h+empty('Nothing found','No subscriptions were found in this sample scan.',false,false)+btn('Back to List','List');return h+'<p class="muted">Choose what to add. Nothing is saved until you confirm.</p><form data-submit="gmail">'+panel([['Netflix','$15.99 · Monthly'],['Spotify','$11.99 · Monthly'],['iCloud+','$2.99 · Monthly']].map(([n,p])=>`<label class="check"><input type="checkbox" checked><span>${n}<small>${p}</small></span></label>`).join(''))+'<details><summary>2 older subscriptions</summary>'+['Adobe','Notion'].map(n=>`<label class="check"><input type="checkbox"><span>${n}</span></label>`).join('')+'</details><button class="primary">Confirm selected</button></form><p class="note">First scan of your first inbox is Free. Ongoing updates require Paid.</p>';}
function profile(up){const incomplete=current.includes('incomplete');return heading('Profile')+(incomplete?panel('<p class="note">Phone, date of birth and gender are optional. You can skip this.</p>'+action('Not now','dismiss','link')):'')+`<div class="${up?'profile-top':''}">${up?'<span class="avatar">AM</span>':''}<div><h3>Alex Morgan</h3><small>alex@example.com</small></div></div>`+panel(fr('Phone',incomplete?'Not set':'+1 202 555 0143')+fr('Date of birth',incomplete?'Not set':'14 Mar 1993')+fr('Gender',incomplete?'Not set':'Not set'))+panel('<span class="metric-label">Paid so far · Estimated</span><p class="hero-price">$1,019</p><small>USD · tracked subscriptions only</small>')+`<div class="rows">${[['Edit profile','Edit profile'],['Change password','Change password'],['History','History'],['Payments','Payments']].map(([a,b])=>btn(a+' <span style="margin-left:auto">›</span>',b,'row')).join('')}</div><h3>Linked inboxes</h3>`+panel(`<small>${incomplete?'No inbox connected':'alex@example.com · Updates paused'}</small>${btn('Connect Gmail','Gmail · scanning','link')}`)+action('Restore purchases','restore','link')+action('Privacy Policy · Terms','legal','link')+btn('Log out','Login','link danger');}
function renderBody(up){
 if(groups.Auth.includes(current))return auth();
 if(current.startsWith('Home'))return home(up);
 if(current.startsWith('List'))return list();
 if(current.startsWith('Detail'))return detail(up);
 if(current==='Add form'||current==='Edit')return addForm(current==='Edit');
 if(current==='Add sheet')return heading('Home',false,true)+stats()+`<div class="overlay"><div class="sheet"><div class="handle"></div><h3>Add a subscription</h3>${btn('Add manually','Add form','secondary')}${btn('Add with AI','AI chat','secondary')}${btn('Use voice','Voice','secondary')}${btn('Connect Gmail','Gmail · scanning','secondary')}${btn('Close','Home','link')}</div></div>`;
 if(current==='AI chat'||current==='Voice')return chat(up);
 if(current.startsWith('Gmail'))return gmail();
 if(current==='Paywall')return heading('Renewless Paid',true)+'<h3>A little help staying on top.</h3><p class="muted">Gmail updates, AI, voice, extra inboxes and more than 25 live subscriptions.</p>'+[['Monthly','$3.99','1 week free'],['3 months','$9.99','1 week free'],['Yearly','$29.99','1 month free']].map(([name,price,trial])=>`<button class="panel plan ${state.plan===name?'active':''}" style="width:100%;text-align:left" data-plan="${name}"><span>${name}<small style="display:block;margin-top:8px">${trial}</small></span><strong>${price}</strong></button>`).join('')+action('Continue with '+state.plan,'purchase','primary')+action('Restore purchases','restore','link')+action('Privacy Policy · Terms','legal','link')+btn('Not now','Home','link')+'<p class="note">Prototype only. No purchase is made.</p>';
 if(current==='Delete confirm')return heading('Detail',true)+`<div class="overlay"><div class="sheet"><h3>Delete subscription?</h3><p>This removes it from Renewless. It does not cancel the real service.</p>${action('Delete from Renewless','delete','primary')}${btn('Keep subscription','Detail','secondary')}</div></div>`;
 if(current==='Widgets')return heading('Home widgets',true)+`<p class="muted">Glanceable snapshots outside the app.</p><div class="widget"><p class="eyebrow">RENEWLESS · UP NEXT</p><h3>Netflix</h3><div class="hero-price">$15.99</div><small>In 3 days · Estimated</small></div><div class="widget"><p class="eyebrow">NEXT 7 DAYS</p>${fr('Netflix','$15.99')}${fr('Spotify','$11.99')}${fr('iCloud+','$2.99')}</div><p class="note">Widget preview. Production reads a local snapshot; no widget API calls.</p>`;
 if(current==='Alerts · empty')return heading('Alerts')+empty('No alerts yet','Reminders show up here after they are sent.');
 if(current==='Alerts')return heading('Alerts')+'<p class="note">Only reminders that have already been sent.</p><div class="rows">'+[['Netflix','24 Oct · 9:00','Renews'],['Spotify','22 Oct · 8:12','Renews'],['iCloud+','18 Oct · 9:00','Access ending']].map(([n,d,k])=>`<button class="row" data-go="Detail" data-name="${n}"><span class="avatar">${n[0]}</span><span class="body"><strong>${n}</strong><small>${d}</small></span><span style="text-align:right">${k}<small>Sent</small></span></button>`).join('')+'</div>';
 if(current.startsWith('Profile'))return profile(up);
 if(current==='Edit profile')return heading('Edit profile',true)+`<form data-submit="Profile">${input('Name','Alex Morgan')}${input('Email','alex@example.com','email')}${input('Phone · optional','','tel')}${input('Date of birth · optional','','date')}<label>Gender · optional<select><option>Not set</option><option>Female</option><option>Male</option><option>Other</option></select></label><button class="primary">Save</button></form>`;
 if(current==='Change password')return heading('Change password',true)+`<form data-submit="Profile">${input('Current password','','password')}${input('New password','','password')}${input('Confirm password','','password')}<button class="primary">Save</button></form><p class="note">Hidden for social accounts without a password.</p>`;
 if(current.startsWith('History'))return heading('History',true)+(current.includes('empty')?empty('Nothing expired or cancelled','Active subscriptions stay on List.',false,false):'<label>Search<input data-search-rows placeholder="Search history"></label><div class="chips">'+['All','Expired','Cancelled'].map(v=>`<button class="chip ${v==='All'?'selected':''}" data-history="${v}">${v}</button>`).join('')+'</div>'+rows('history'));
 if(current.startsWith('Payments'))return heading('Payments',true)+(current.includes('empty')?empty('No charges yet','This stays empty until a tracked charge is available.',false,false):panel('<span class="metric-label">Paid so far · USD</span><p class="hero-price">$1,019</p><small>Estimated from your tracked subscriptions</small>')+'<h3>This month <small style="float:right">$86</small></h3>'+rows()+'<p class="note">Amounts are grouped by currency. No currency conversion.</p>');
 return '';
}
function isTab(){return /^(Home|List|Alerts|Profile)( ·|$)/.test(current)}
function render(){document.getElementById('title').textContent=current;document.getElementById('context').textContent='Compare the same screen and state. Use the screen library or tap through the phone controls; both versions stay in sync.';for(const id of ['baseline','upgraded']){const p=document.getElementById(id);p.innerHTML=`<div class="status"><span>9:41</span><span class="island"></span><span>▂▄▆ ▰</span></div><div class="content ${isTab()?'has-tabs':''}">${renderBody(id==='upgraded')}</div>${isTab()?tabs():''}<div class="homebar"></div>`;}renderNav();}
function renderNav(){const q=document.getElementById('search').value.toLowerCase();document.getElementById('screens').innerHTML=Object.entries(groups).map(([group,names])=>{const found=names.filter(s=>s.toLowerCase().includes(q));return found.length?`<section><h3>${group}</h3>${found.map(s=>`<button class="${s===current?'active':''}" data-go="${escape(s)}" ${s===current?'aria-current="page"':''}>${s}</button>`).join('')}</section>`:'';}).join('');}
function go(name){if(name==='back')name=previous===current?'Home':previous;if(!screens.includes(name))return;previous=current;current=name;history.replaceState(null,'','#'+slug(name));render();}
let toastTimer;function toast(s){const t=document.getElementById('toast');t.textContent=s;t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.hidden=true,4000);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.go){if(b.dataset.name)demoName=b.dataset.name;if(b.dataset.price)demoPrice=b.dataset.price;go(b.dataset.go);}else if(b.dataset.cycle){state.cycle=b.dataset.cycle;document.querySelectorAll('[data-cycle]').forEach(x=>x.classList.toggle('selected',x.dataset.cycle===state.cycle));}else if(b.dataset.plan){state.plan=b.dataset.plan;render();}else if(b.dataset.history){document.querySelectorAll('[data-history]').forEach(x=>x.classList.toggle('selected',x.dataset.history===b.dataset.history));document.querySelectorAll('.phone .row').forEach(x=>x.hidden=b.dataset.history!=='All'&&!x.textContent.includes(b.dataset.history));}else if(b.dataset.action){switch(b.dataset.action){case 'reminder':state.reminder=!state.reminder;render();break;case 'loop':if(!matchMedia('(prefers-reduced-motion: reduce)').matches)b.animate([{transform:'rotate(0)'},{transform:'rotate(-7deg)'},{transform:'rotate(0)'}],{duration:400});break;case 'keep':toast('Kept in this demo. Your subscription is unchanged.');break;case 'cancel-intent':toast('Cancel on the service, then record it in Renewless.');break;case 'create-ai':demoName='Duolingo';demoPrice='9.99';state.created=true;go('Detail');toast('Created in the demo only.');break;case 'delete':go('List · empty');toast('Removed from this demo only.');break;case 'dismiss':go('Profile');break;case 'attach':b.closest('.content').querySelector('.attachment').click();break;case 'purchase':toast('Demo only — '+state.plan+' selected. No payment is taken.');break;case 'restore':toast('Demo only — no store account connected.');break;case 'legal':toast('Legal links will be connected before release. No purchase is available here.');break;case 'resend':toast('Preview only. A real code can be resent after 2 minutes.');break;}}});
document.addEventListener('submit',e=>{const form=e.target.closest('form[data-submit]');if(!form)return;e.preventDefault();const destination=form.dataset.submit;if(destination==='save-sub'){demoName=form.elements.name.value;demoPrice=Number(form.elements.price.value).toFixed(2);state.created=true;go('Detail');toast('Saved in the demo only.');}else if(destination==='chat'){toast('Visual prototype: conversation is scripted; no message is sent.');}else if(destination==='gmail'){if(!form.querySelector('input:checked'))return toast('Select at least one subscription.');go('List');toast('Sample subscriptions confirmed. No Gmail access used.');}else{const passwords=form.querySelectorAll('input[type=password]');if(passwords.length>1&&passwords[passwords.length-1].value!==passwords[passwords.length-2].value)return toast('Passwords do not match.');go(destination);}});
document.addEventListener('input',e=>{if(e.target.matches('[data-search-rows]')){const q=e.target.value.toLowerCase();e.target.closest('.content').querySelectorAll('.row').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q));}});
document.addEventListener('change',e=>{if(e.target.matches('.attachment')&&e.target.files.length)toast('Image selected locally. This prototype does not upload or analyze it.');});
document.getElementById('search').oninput=renderNav;
document.getElementById('mode').onchange=e=>document.getElementById('comparison').dataset.mode=e.target.value;
document.getElementById('reset').onclick=()=>{state.reminder=true;state.cycle='Monthly';state.plan='Monthly';state.created=false;demoName='Netflix';demoPrice='15.99';go('Home');toast('Demo reset.');};
window.addEventListener('hashchange',()=>{const name=screens.find(s=>slug(s)===location.hash.slice(1));if(name)go(name);});
current=screens.find(s=>slug(s)===location.hash.slice(1))||'Home';render();
